//! 📋️ Exact whole replacements compare original typed vectors and move each funded payload into ascending sparse rows.
use super::RetainedFieldChange;
use semio_framework_value::{RetirementDemand, ValueError, ValueRefusalKind, retirement::RetireOwned, retained_clone::{RetainedClone, RetainedCloneRef, RetainedCloneClose, RetainedCloneGrant, RetainedCloneProgress, RetainedCloneStep, retained_clone_grant_admits}};
use semio_framework_value_persistent::retained_equality::RetainedEquality;
use std::{collections::VecDeque,mem::{size_of,ManuallyDrop}};
const META:usize=size_of::<usize>()*8+3;
fn invalid(text:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,text)}
fn capacity<T>(len:usize)->Result<usize,ValueError>{len.checked_mul(size_of::<T>()).ok_or_else(||ValueError::literal(ValueRefusalKind::OwnershipLimit,"indexed replacement native capacity overflow"))}
fn scalar(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
fn nested(mut d:RetirementDemand)->RetirementDemand{d.copy_bytes+=META;d.depth+=1;d}
fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-META,maximum_depth:g.maximum_depth-1,..g}}
fn receipt(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_bytes+=META;p}
/// 🎯️ Original base ordinals are removed; authored rows are added at exact ascending final positions.
#[derive(semio_framework_value::RetireOwned)]
pub struct IndexedReplacement<A:RetireOwned>{pub removed:Vec<usize>,pub added:Vec<A>}
/// 🧳️ The mapper moves one typed payload header without allocation, traversal or payload destruction.
pub struct RetainedIndexedReplacement<T:RetainedEquality+RetainedClone,A:RetireOwned>{field:RetainedFieldChange<Vec<T>>,source:ManuallyDrop<Option<VecDeque<T>>>,removed:ManuallyDrop<Option<Vec<usize>>>,added:ManuallyDrop<Option<Vec<A>>>,retirement:RetainedCloneClose,map:fn(usize,T)->A,old_len:usize,new_len:usize,index:usize,changed:bool,phase:u8,closing:bool}
impl<T:RetainedEquality+RetainedClone,A:RetireOwned> RetainedIndexedReplacement<T,A>{
 pub fn new(map:fn(usize,T)->A)->Self{Self{field:Default::default(),source:ManuallyDrop::new(None),removed:ManuallyDrop::new(None),added:ManuallyDrop::new(None),retirement:Default::default(),map,old_len:0,new_len:0,index:0,changed:false,phase:0,closing:false}}
 pub fn ready(&self)->bool{self.phase==8&&!self.closing}
 pub fn demand(&self,a:RetainedCloneRef<'_,Vec<T>>,o:RetainedCloneRef<'_,Vec<T>>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.phase>8{return Err(invalid("indexed original decision settled or closing"));}self.field.verify_sources(a,o)?;Ok(match self.phase{0=>nested(self.field.decision_demand(a,o,body.saturating_sub(META))?),1=>{let mut d=self.field.change_demand()?;d.copy_bytes+=META+size_of::<VecDeque<T>>()*2+size_of::<Vec<T>>()*2+size_of::<usize>()*3;d.depth+=1;d},2=>RetirementDemand{capacity_bytes:capacity::<usize>(self.old_len)?,..scalar(META+size_of::<Vec<usize>>()*2)},3=>RetirementDemand{capacity_bytes:capacity::<A>(self.new_len)?,..scalar(META+size_of::<Vec<A>>()*2)},4=>scalar(META+size_of::<usize>()*3),5=>scalar(META+size_of::<Option<T>>()*2+size_of::<A>()*2),6=>RetirementDemand{release_bytes:capacity::<T>(self.source.as_ref().unwrap().capacity())?,..scalar(META+size_of::<Option<VecDeque<T>>>()*2)},8=>self.take_demand()?,_=>return Err(invalid("indexed original phase is invalid"))})}
 pub fn advance(&mut self,a:RetainedCloneRef<'_,Vec<T>>,o:RetainedCloneRef<'_,Vec<T>>,body:usize,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.demand(a,o,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}let mut p=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};match self.phase{0=>{p=receipt(self.field.decide(a,o,body.saturating_sub(META),child(g))?.progress());if self.field.ready(){self.phase=1;}},1=>{let fixed=META+size_of::<VecDeque<T>>()*2+size_of::<Vec<T>>()*2+size_of::<usize>()*3;let(value,mut progress)=self.field.take_change(RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-fixed,maximum_depth:g.maximum_depth-1,..g})?.unwrap();self.old_len=o.get().len();if let Some(value)=value{self.new_len=value.len();*self.source=Some(VecDeque::from(value));self.changed=true;self.phase=2;}else{self.phase=8;}progress.copied_bytes+=fixed;p=progress;},2=>{let mut v=Vec::new();v.try_reserve_exact(self.old_len).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"indexed removed row allocation refused"))?;p.retained_capacity_bytes=capacity::<usize>(v.capacity())?;*self.removed=Some(v);self.phase=3;},3=>{let mut v=Vec::new();v.try_reserve_exact(self.new_len).map_err(|_|ValueError::literal(ValueRefusalKind::AllocationFailed,"indexed added row allocation refused"))?;p.retained_capacity_bytes=capacity::<A>(v.capacity())?;*self.added=Some(v);self.index=0;self.phase=4;},4=>{if self.index==self.old_len{self.index=0;self.phase=5;}else{self.removed.as_mut().unwrap().push(self.index);self.index+=1;}},5=>{if let Some(value)=self.source.as_mut().unwrap().pop_front(){self.added.as_mut().unwrap().push((self.map)(self.index,value));self.index+=1;}else{self.phase=6;}},6=>{assert!(self.source.as_ref().unwrap().is_empty());drop(self.source.take());p.released_bytes=d.release_bytes;self.phase=8;},8=>return Ok(RetainedCloneStep::Complete(Default::default())),_=>unreachable!()}Ok(if self.ready(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.ready(){return Err(invalid("indexed original replacement is pending"));}Ok(scalar(META+size_of::<Option<IndexedReplacement<A>>>()*2))}
 pub fn take(&mut self,g:RetainedCloneGrant)->Result<Option<(Option<IndexedReplacement<A>>,RetainedCloneProgress)>,ValueError>{let d=self.take_demand()?;if !retained_clone_grant_admits(g,d){return Ok(None);}self.phase=9;let result=if self.changed{Some(IndexedReplacement{removed:self.removed.take().unwrap(),added:self.added.take().unwrap()})}else{None};Ok(Some((result,RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()})))}
 pub fn begin_close(&mut self){self.closing=true;self.field.begin_close();}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid("indexed original close not begun"));}let body=body.saturating_sub(META);if !self.field.terminal_is_empty(){return Ok(nested(self.field.close_demand(body)?));}if !self.retirement.is_empty()||self.source.is_some(){return Ok(nested(self.retirement.next_owner_demands::<VecDeque<T>>(self.source.is_some(),&None,body)?));}if self.removed.is_some(){return Ok(nested(self.retirement.next_owner_demands::<Vec<usize>>(true,&None,body)?));}if self.added.is_some(){return Ok(nested(self.retirement.next_owner_demands::<Vec<A>>(true,&None,body)?));}Ok(Default::default())}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()));}if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}if !self.field.terminal_is_empty(){return self.field.close_step(child(g)).map(|s|RetainedCloneStep::Progress(receipt(s.progress())));}if !self.retirement.is_empty(){return self.retirement.step_granted(child(g)).map(|s|RetainedCloneStep::Progress(receipt(s.progress())));}if let Some(step)=self.retirement.begin_granted(&mut self.source,child(g))?{return Ok(RetainedCloneStep::Progress(receipt(step.progress())));}if let Some(step)=self.retirement.begin_granted(&mut self.removed,child(g))?{return Ok(RetainedCloneStep::Progress(receipt(step.progress())));}if let Some(step)=self.retirement.begin_granted(&mut self.added,child(g))?{return Ok(RetainedCloneStep::Progress(receipt(step.progress())));}Ok(RetainedCloneStep::Complete(Default::default()))}
 pub fn terminal_is_empty(&self)->bool{self.closing&&self.field.terminal_is_empty()&&self.source.is_none()&&self.removed.is_none()&&self.added.is_none()&&self.retirement.is_empty()}
}
impl<T:RetainedEquality+RetainedClone,A:RetireOwned> Drop for RetainedIndexedReplacement<T,A>{fn drop(&mut self){let empty=self.terminal_is_empty();assert!(std::thread::panicking()||empty,"indexed original source/deque/output custody requires explicit closure");if empty{unsafe{ManuallyDrop::drop(&mut self.source);ManuallyDrop::drop(&mut self.removed);ManuallyDrop::drop(&mut self.added);}}}}
#[cfg(test)] #[path="🧪️tests/🦀️.rs"] mod tests;
